// Neutral static adaptation of prototype-v24.ts drawVapor/drawBackrooms/drawPerspectiveFloor.
// No artist assets, media URLs, network, timers, animation or global surface targets.
export function attachEnvironment({host,scene,signal,validate,apply,getTargets=()=>[],resolveTarget=()=>null}){
 const doc=host.ownerDocument;let disposed=false,backdrop=null;
 host.innerHTML='<h2>Room environment</h2><p>Static source-derived procedural backdrop within this room. No animation, media compositor or global wallpaper. Changes belong to the room backup (format v5). Object targets use reviewed IDs and stay within Foundry.</p><label>Surface <select data-environment-target><option value="room">Room backdrop</option><option value="object">Object surface</option></select></label><label>Object target <select data-environment-target-id></select></label><label>Backdrop <select data-environment-preset><option value="off">Off</option><option value="vapor">Vapor</option><option value="backrooms">Backrooms</option></select></label><label>Opacity <input data-environment-opacity type="number" min="0" max="1" step="0.01" value="0.82"></label><label>Vapor horizon <input data-environment-horizon type="number" min="0.1" max="0.9" step="0.01" value="0.48"></label><button type="button" data-environment-apply>Apply room environment</button><p data-environment-status role="status"></p>';
 const one=s=>host.querySelector(s),status=one('[data-environment-status]');
 function clear(){backdrop?.remove();backdrop=null;}
 function update(input){if(disposed||signal.aborted)return;const v=validate(input??{preset:'off',opacity:.82,horizon:.48});backdrop?.remove();backdrop=null;const targetSelect=one('[data-environment-target-id]');targetSelect.replaceChildren();for(const obj of getTargets()){const option=doc.createElement('option');option.value=obj.id;option.textContent=obj.name;targetSelect.append(option);}if(v.targetId&&!getTargets().some(o=>o.id===v.targetId)){const option=doc.createElement('option');option.value=v.targetId;option.textContent='Unavailable instance: '+v.targetId;targetSelect.append(option);}one('[data-environment-target]').value=v.target||'room';targetSelect.value=v.targetId||getTargets()[0]?.id||'';one('[data-environment-preset]').value=v.preset;one('[data-environment-opacity]').value=String(v.opacity);one('[data-environment-horizon]').value=String(v.horizon);if(v.preset==='off'){status.textContent='Room backdrop off; configuration retained.';return;}
  const surface=v.target==='object'?resolveTarget(v.targetId):scene;if(!surface){status.textContent='Object surface unavailable or hidden; target and configuration retained without fallback.';return;}
  const ns='http://www.w3.org/2000/svg',svg=doc.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 1000 600');svg.setAttribute('preserveAspectRatio','none');svg.setAttribute('aria-hidden','true');svg.dataset.environmentBackdrop=v.preset;svg.style.cssText=`position:absolute;inset:0;width:100%;height:100%;pointer-events:none;opacity:${v.opacity}`;
  const add=(tag,attrs)=>{const e=doc.createElementNS(ns,tag);for(const [k,value] of Object.entries(attrs))e.setAttribute(k,String(value));svg.append(e);return e;};
  const colors=v.preset==='vapor'?['#14072e','#5e1d79','#ff6aae']:['#b8ac61','#807744','#393520'];
  svg.style.background=`linear-gradient(to bottom,${colors.join(',')})`; // Original three-stop sky gradient, no document-global ids.
  const line=(x1,y1,x2,y2,stroke)=>add('line',{x1,y1,x2,y2,stroke,'stroke-width':1});
  if(v.preset==='vapor'){const y=204,r=102;add('circle',{cx:500,cy:y,r,fill:'#ffd45c'});for(let i=0;i<6;i++)add('rect',{x:500-r,y:y-r+i*r*.35,width:r*2,height:5,fill:'rgba(255,72,172,.85)'});const horizon=600*v.horizon;for(let i=-12;i<=12;i++)line(500+i*7,horizon,500+i*120,600,'rgba(68,242,255,.5)');for(let y=horizon+10;y<600;y+=Math.max(9,(y-horizon)*.18))line(0,y,1000,y,'rgba(68,242,255,.5)');}
  else{const horizon=252;for(let x=0;x<1000;x+=125){line(x,0,500+(x-500)*.28,horizon,'rgba(55,51,25,.55)');line(500+(x-500)*.28,horizon,x,600,'rgba(55,51,25,.55)');}for(let y=0;y<600;y+=32)line(0,y,1000,y,'rgba(55,51,25,.55)');for(let i=0;i<5;i++)add('rect',{x:1000*(.08+i*.2),y:48,width:110,height:5,fill:'rgba(255,252,195,.78)'});}
  surface.prepend(svg);backdrop=svg;status.textContent='Static '+v.preset+' '+(v.target==='object'?'object surface':'room backdrop')+' rendered; no media playback or motion.';
 }
 const click=()=>{if(disposed||signal.aborted)return;try{const raw=[one('[data-environment-opacity]').value,one('[data-environment-horizon]').value];if(raw.some(v=>!v.trim()))throw Error('Opacity and horizon are required.');const v=validate({preset:one('[data-environment-preset]').value,opacity:Number(raw[0]),horizon:Number(raw[1]),target:one('[data-environment-target]').value,targetId:one('[data-environment-target]').value==='object'?one('[data-environment-target-id]').value:null});apply(v);}catch(e){status.textContent='Environment not applied: '+e.message;}};
 one('[data-environment-apply]').addEventListener('click',click);const dispose=()=>{if(disposed)return;disposed=true;backdrop?.remove();backdrop=null;one('[data-environment-apply]').removeEventListener('click',click);signal.removeEventListener('abort',dispose);};signal.addEventListener('abort',dispose,{once:true});return {update,clear,dispose};
}
